#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "pnp_graph.h"

static volatile uint64_t sink;
static pnp_config_t base(uint32_t mask){pnp_config_t c;memset(&c,0,sizeof(c));c.predicate=(uint8_t)PNP_PRED_ALWAYS;c.emit_true=mask;return c;}
static void primitive_bench(const char *name,pnp_config_t c){const uint64_t iterations=UINT64_C(1000000);pnp_state_t s={{0}},out;pnp_event_t e={0};pnp_output_buffer_t outputs;clock_t begin=clock();for(uint64_t i=0u;i<iterations;++i){(void)pnp_execute(&c,&s,&e,&out,&outputs);sink^=out.words[0]+outputs.count;}double seconds=(double)(clock()-begin)/(double)CLOCKS_PER_SEC;printf("%-18s ns/op=%8.2f ops/s=%12.0f\n",name,seconds*1e9/(double)iterations,(double)iterations/seconds);}
static void chain_bench(uint32_t count,const char *name){const uint64_t iterations=UINT64_C(100000);pnp_node_t nodes[16];pnp_state_domain_t domains[16];pnp_edge_t edges[16];pnp_graph_event_t storage[4];pnp_queue_t q;pnp_graph_output_t item;pnp_graph_output_buffer_t out;pnp_run_stats_t stats;pnp_event_t event={0};pnp_graph_t g={nodes,count,16u,edges,count,16u,domains,count,16u};memset(nodes,0,sizeof(nodes));memset(domains,0,sizeof(domains));for(uint32_t i=0u;i<count;++i){nodes[i].config=base(1u);nodes[i].state_domain=i;edges[i]=(pnp_edge_t){i,0u,i+1u<count?i+1u:PNP_EXTERNAL_NODE,0u};}clock_t begin=clock();for(uint64_t i=0u;i<iterations;++i){out=(pnp_graph_output_buffer_t){&item,1u,0u};pnp_queue_init(&q,storage,4u);(void)pnp_graph_inject(&q,0u,0u,&event);(void)pnp_graph_run(&g,&q,&out,(pnp_run_limits_t){count,count},&stats);sink^=stats.steps+out.count;}double seconds=(double)(clock()-begin)/(double)CLOCKS_PER_SEC;printf("%-18s ns/input=%8.2f inputs/s=%9.0f primitive/s=%9.0f\n",name,seconds*1e9/(double)iterations,(double)iterations/seconds,(double)(iterations*count)/seconds);}
static void retry_bench(void){const uint64_t iterations=UINT64_C(100000);pnp_node_t n[5];pnp_state_domain_t d;pnp_edge_t e[6];pnp_graph_event_t storage[8];pnp_queue_t q;pnp_graph_output_t items[2];pnp_graph_output_buffer_t out;pnp_run_stats_t stats;pnp_event_t event={0};pnp_graph_t g={n,5u,5u,e,6u,6u,&d,1u,1u};memset(n,0,sizeof(n));event.type=2u;n[0].config=base(1u);n[0].config.source_a.kind=(uint8_t)PNP_SRC_TYPE;n[0].config.predicate=(uint8_t)PNP_PRED_EQ;n[0].config.compare_source.kind=(uint8_t)PNP_SRC_CONSTANT;n[0].config.compare_source.immediate=2u;n[1].config=base(1u);n[1].config.source_a.kind=(uint8_t)PNP_SRC_STATE_WORD;n[1].config.source_a.index=1u;n[1].config.predicate=(uint8_t)PNP_PRED_EQ;n[1].config.compare_source.kind=(uint8_t)PNP_SRC_ONE;n[2].config=base(1u);n[2].config.source_a.kind=(uint8_t)PNP_SRC_STATE_WORD;n[2].config.event_update_destination=(uint8_t)PNP_EVENT_DEST_SEQUENCE;n[3].config=base(1u);n[3].config.source_a.kind=(uint8_t)PNP_SRC_STATE_WORD;n[3].config.source_a.index=2u;n[3].config.source_b.kind=(uint8_t)PNP_SRC_ONE;n[3].config.alu_op=(uint8_t)PNP_ALU_ADD;n[3].config.update_mode=(uint8_t)PNP_UPDATE_RESULT;n[3].config.update_index=2u;n[3].config.event_update_destination=(uint8_t)PNP_EVENT_DEST_TYPE;n[3].config.event_update_source=(uint8_t)PNP_EVENT_VALUE_CONSTANT;n[3].config.event_update_constant=4u;n[4].config=base(1u);e[0]=(pnp_edge_t){0u,0u,1u,0u};e[1]=(pnp_edge_t){1u,0u,2u,0u};e[2]=(pnp_edge_t){2u,0u,3u,0u};e[3]=(pnp_edge_t){3u,0u,PNP_EXTERNAL_NODE,1u};e[4]=(pnp_edge_t){3u,1u,4u,0u};e[5]=(pnp_edge_t){4u,0u,PNP_EXTERNAL_NODE,2u};clock_t begin=clock();for(uint64_t i=0u;i<iterations;++i){memset(&d,0,sizeof(d));d.state.words[0]=77u;d.state.words[1]=1u;out=(pnp_graph_output_buffer_t){items,2u,0u};pnp_queue_init(&q,storage,8u);(void)pnp_graph_inject(&q,0u,0u,&event);(void)pnp_graph_run(&g,&q,&out,(pnp_run_limits_t){8u,8u},&stats);sink^=stats.steps+out.count;}double seconds=(double)(clock()-begin)/(double)CLOCKS_PER_SEC;printf("%-18s ns/input=%8.2f inputs/s=%9.0f primitive/s=%9.0f\n","retry graph",seconds*1e9/(double)iterations,(double)iterations/seconds,(double)(iterations*4u)/seconds);}
int main(void){pnp_config_t c;c=base(1u);primitive_bench("pass",c);c.source_a.kind=(uint8_t)PNP_SRC_CONSTANT;c.source_a.immediate=1u;c.source_b.kind=(uint8_t)PNP_SRC_ONE;c.alu_op=(uint8_t)PNP_ALU_ADD;primitive_bench("ADD",c);c.alu_op=(uint8_t)PNP_ALU_XOR;primitive_bench("XOR",c);c.predicate=(uint8_t)PNP_PRED_EQ;c.compare_source.kind=(uint8_t)PNP_SRC_ONE;primitive_bench("predicate true",c);c.compare_source.kind=(uint8_t)PNP_SRC_ZERO;primitive_bench("predicate false",c);c=base(1u);c.update_mode=(uint8_t)PNP_UPDATE_CONSTANT;c.update_constant=1u;primitive_bench("state update",c);c=base(1u);c.event_update_destination=(uint8_t)PNP_EVENT_DEST_FLAGS;c.event_update_source=(uint8_t)PNP_EVENT_VALUE_CONSTANT;c.event_update_constant=1u;primitive_bench("event mutation",c);c=base(0xffu);primitive_bench("max fan-out",c);chain_bench(4u,"graph chain 4");chain_bench(16u,"graph chain 16");retry_bench();printf("sink=%" PRIu64 "\n",sink);return 0;}
